-- Quy cách cây = kích thước CÂY (chiều cao, dáng, số lá…), không gộp cỡ chậu (08/10/2026, chủ shop: "chậu bán riêng, cây bán riêng";
-- chậu ghi kích thước dài × cao, vd. 8x8cm, bán ở danh mục Chậu). Với 217 cây nạp ở 0034/0035: bỏ phần "Chậu 25cm" / "Container/bầu"
-- khỏi tên quy cách ("Chậu 20–25cm, cao 40–60cm" → "Cao 40–60cm"), gộp quy cách trùng sau khi bỏ (23 cây), bỏ thông số "Chậu",
-- viết lại mô tả ngắn (nếu admin chưa sửa).
-- Cây chưa bán / chưa ai đụng (quy cách + giá còn đúng như 0035, chưa có đơn, lịch sử kho chỉ có "Tồn đầu kỳ" của Hệ thống) → dựng lại
-- quy cách + tồn 10 mỗi quy cách. Cây đã có đơn hoặc admin đã sửa → chỉ đổi tên quy cách còn đúng tên cũ (không xóa quy cách vì đơn tham chiếu theo thứ tự).
CREATE TEMP TABLE "_m36_plan" ("slug" text PRIMARY KEY, "old" jsonb, "new" jsonb, "oldmap" jsonb, "old_lead" text, "lead" text, "chau" text);--> statement-breakpoint
CREATE TEMP TABLE "_m36_rebuild" AS
SELECT m.slug FROM "_m36_plan" m
WHERE coalesce((SELECT jsonb_agg(jsonb_build_object('label', o.label, 'price', o.price) ORDER BY o.idx) FROM "product_options" o WHERE o.product_slug = m.slug), '[]'::jsonb) = m.old
  AND NOT EXISTS (SELECT 1 FROM "order_items" i WHERE i.product_slug = m.slug)
  AND NOT EXISTS (SELECT 1 FROM "stock_moves" s WHERE s.product_slug = m.slug AND (s.actor <> 'Hệ thống' OR s.reason <> 'import'));--> statement-breakpoint
DELETE FROM "stock_moves" WHERE "product_slug" IN (SELECT slug FROM "_m36_rebuild");--> statement-breakpoint
DELETE FROM "stock_lots" WHERE "product_slug" IN (SELECT slug FROM "_m36_rebuild");--> statement-breakpoint
DELETE FROM "product_options" WHERE "product_slug" IN (SELECT slug FROM "_m36_rebuild");--> statement-breakpoint
SELECT m.slug, (n.ord - 1)::int, n.value->>'label', (n.value->>'price')::int, 0
FROM "_m36_plan" m JOIN "_m36_rebuild" r ON r.slug = m.slug, jsonb_array_elements(m.new) WITH ORDINALITY AS n(value, ord);--> statement-breakpoint
WITH st AS (SELECT id FROM "stores" ORDER BY is_default DESC, id LIMIT 1),
tgt AS (
  SELECT o.product_slug, o.idx FROM "product_options" o, st
  WHERE o.stock = 0 AND o.price > 0 AND o.product_slug IN (SELECT slug FROM "_m36_rebuild")
),
lots AS (
  SELECT st.id, t.product_slug, t.idx, 10 FROM tgt t, st
  RETURNING id, store_id, product_slug, option_idx
),
mv AS (
  SELECT product_slug, option_idx, store_id, id, 10, 10, 'import', 'Tồn đầu kỳ', 'Hệ thống' FROM lots
)
UPDATE "product_options" o SET "stock" = 10 FROM tgt t WHERE o.product_slug = t.product_slug AND o.idx = t.idx;--> statement-breakpoint
-- Cây không dựng lại được: chỉ đổi tên những quy cách còn đúng tên cũ
UPDATE "product_options" o SET "label" = x.new_label
FROM (
  SELECT m.slug, e.key AS old_label, e.value AS new_label
  FROM "_m36_plan" m, jsonb_each_text(m.oldmap) e
  WHERE m.slug NOT IN (SELECT slug FROM "_m36_rebuild")
) x
WHERE o.product_slug = x.slug AND o.label = x.old_label AND x.new_label IS NOT NULL;--> statement-breakpoint
UPDATE "products" p SET "specs" = coalesce((SELECT jsonb_agg(e ORDER BY k) FROM jsonb_array_elements(p.specs) WITH ORDINALITY AS z(e, k) WHERE e <> jsonb_build_array('Chậu', m.chau)), '[]'::jsonb)
FROM "_m36_plan" m WHERE p.slug = m.slug AND m.chau IS NOT NULL;--> statement-breakpoint
UPDATE "products" p SET "lead" = m.lead FROM "_m36_plan" m WHERE p.slug = m.slug AND p.lead = m.old_lead;--> statement-breakpoint
-- Chậu bán riêng: thông số điền sẵn của danh mục Chậu ghi rõ kích thước dài × cao (chỉ khi bộ thông số còn mặc định)
UPDATE "categories" SET "specs" = '[{"name":"Kích thước (dài × cao)"},{"name":"Chất liệu"},{"name":"Quy cách"}]'::jsonb
WHERE "slug" = 'chau' AND "specs" = '[{"name":"Kích thước"},{"name":"Chất liệu"},{"name":"Quy cách"}]'::jsonb;--> statement-breakpoint
DROP TABLE "_m36_rebuild";--> statement-breakpoint
DROP TABLE "_m36_plan";
